async function marketplace(){app.innerHTML=shell(`<div class="dashboard"><div class="dash-container"><div class="path-head"><div><h1 class="page-title">Marketplace</h1><p class="secondary-text">${tr('מסלולים של יוצרים. נתוני Demo מסומנים ואינם מכירות אמיתיות.','Creator paths. Demo data is clearly labeled and not real sales.')}</p></div><div class="actions"><span class="badge info">DEMO DATA</span>${state.user?.features?.canPublishMarketplacePath?`<button class="btn primary" id="create-market-path">${tr('יצירת מסלול','Create path')}</button>`:''}</div></div><div class="filters"><input id="market-q" placeholder="${tr('חיפוש מסלול','Search paths')}"><select id="market-cat"><option value="">${tr('כל הקטגוריות','All categories')}</option>${(state.config?.categories||[]).map(x=>`<option>${h(x)}</option>`).join('')}</select><select id="market-price"><option value="">${tr('כל המחירים','All prices')}</option><option value="free">${tr('חינם','Free')}</option><option value="paid">${tr('בתשלום','Paid')}</option></select></div><div id="market-list">${loading()}</div></div></div>`,'market');bindGlobal();const load=async()=>{try{const q=encodeURIComponent(qs('#market-q').value),cat=encodeURIComponent(qs('#market-cat').value),price=encodeURIComponent(qs('#market-price').value),d=await api(`/api/marketplace?q=${q}&category=${cat}&price=${price}`);qs('#market-list').innerHTML=d.paths.length?`<div class="market-grid">${d.paths.map(x=>`<article class="market-card"><div><div class="actions" style="justify-content:space-between"><span class="badge">${h(x.category)}</span><span class="badge info">DEMO</span></div><h3>${h(x.title)}</h3><p>${h(x.description)}</p></div><footer><div><strong>${x.price?`₪${h(x.price)}`:tr('חינם','Free')}</strong><div class="muted tiny">${h(x.rating.toFixed(1))}/5 · ${h(x.learners)} ${tr('לומדים','learners')}</div></div><div class="actions">${x.started?`<button class="btn primary" data-go="/path/${h(x.pathSlug)}">${tr('פתיחה','Open')}</button>`:`<button class="btn primary buy-market" data-id="${h(x.id)}">${x.price?tr('רכישה','Buy'):tr('הוספה','Add')}</button>`}<button class="btn tertiary fav" data-id="${h(x.id)}">${x.favorite?tr('במועדפים','Favorited'):tr('שמירה','Save')}</button><button class="btn secondary report" data-id="${h(x.id)}">${tr('דיווח','Report')}</button></div></footer></article>`).join('')}</div>`:`<div class="state">${tr('לא נמצאו מסלולים שמתאימים לסינון.','No paths match the filters.')}</div>`;bindGlobal();qsa('.fav').forEach(b=>b.onclick=async()=>{try{await api(`/api/marketplace/${b.dataset.id}/favorite`,{method:'POST',body:'{}'});load()}catch(e){toast(e.message,'error')}});qsa('.report').forEach(b=>b.onclick=()=>reportModal(b.dataset.id));qsa('.buy-market').forEach(b=>b.onclick=()=>marketOrder(b.dataset.id))}catch(e){qs('#market-list').innerHTML=errorState(e.message)}};let timer;['market-q','market-cat','market-price'].forEach(id=>qs('#'+id).addEventListener(id==='market-q'?'input':'change',()=>{clearTimeout(timer);timer=setTimeout(load,180)}));qs('#create-market-path')?.addEventListener('click',creatorPathModal);load()}
