async function pricingPage(){app.innerHTML=shell(`<div class="dashboard"><div class="dash-container"><div class="path-head"><div><h1 class="page-title">${tr('תוכניות ומחירים','Plans & pricing')}</h1><p class="secondary-text">${tr('אין רכישת תשובות או ניקוד. מנויים פותחים גישה וכלים בלבד.','Plans unlock access and tools, never answers or fake score.')}</p></div></div>${pricingSection().replace('<section class="section" id="pricing"><div class="container">','<section><div>').replace('</div></section>','</div></section>')}<div class="table-wrap" style="margin-top:28px"><table class="compare"><thead><tr><th>${tr('תכונה','Feature')}</th><th>Free</th><th>Basic ₪${state.config.prices.basic}</th><th>Plus ₪${state.config.prices.plus}</th><th>Pro ₪${state.config.prices.pro}</th></tr></thead><tbody>${[['מסלול פעיל','1','1','עד 5','ללא הגבלה סבירה'],['משימות יומיות','בסיסי','בסיסי','מותאם','מתקדם'],['משחקי 3D מלאים','לא','כן','כן','כן'],['Boss שבועי','לא','כן','כן','כן'],['מאמן AI','מוגבל','מוגבל','מוגדל','מתקדם'],['עולמות מיוחדים','לא','בסיסיים','נוספים','כולם'],['היסטוריית משחקים','לא','14 ימים','מלאה','מלאה ומתקדמת'],['יצירת מסלולים','לא','לא','לא','כן'],['Marketplace ליוצרים','לא','לא','לא','כן']].map(r=>`<tr>${r.map(x=>`<td>${h(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="panel" style="margin-top:22px"><h2 class="section-title">${tr('הזמנות bit שלי','My bit orders')}</h2><div id="orders-list">${loading()}</div></div></div></div>`,'settings');bindGlobal();bindBuy();loadOrders()}
