function showPaymentModal(d){
  const order=d.order;
  const m=modal(`<span class="badge warning">${tr('בדיקה ידנית','MANUAL REVIEW')}</span><h2>${tr('תשלום באמצעות bit','Pay with bit')}</h2><p>${h(d.message)}</p><div class="panel"><div class="activity-row"><span>${tr('פריט','Item')}</span><strong>${h(order.itemTitle||order.planId?.toUpperCase()||order.itemId)}</strong></div><div class="activity-row"><span>${tr('סכום מדויק','Exact amount')}</span><strong>₪${h(order.priceNis)}</strong></div><div class="activity-row"><span>${tr('מספר bit','bit phone')}</span><strong id="bit-phone">${h(d.bitPhone)}</strong></div><div class="activity-row"><span>${tr('מספר הזמנה','Order number')}</span><code>${h(order.id)}</code></div></div><p class="small secondary-text">${tr('פתח bit, שלח את הסכום המדויק למספר שמופיע למעלה, וציין את מספר ההזמנה בהערת ההעברה. לאחר מכן העלה צילום מסך או PDF.','Open bit, send the exact amount to the number above, include the order number in the transfer note, then upload proof.')}</p><div class="actions" style="flex-wrap:wrap"><button class="btn secondary" id="copy-phone">${tr('העתקת המספר','Copy number')}</button>${d.bitUrl?`<a class="btn primary" href="${h(d.bitUrl)}" rel="noopener">${tr('מעבר לתשלום ב־bit','Open bit payment')}</a>`:''}</div><form id="proof-form" style="margin-top:18px"><div class="field"><label>${tr('אישור תשלום','Payment proof')}</label><input type="file" name="proof" accept="image/png,image/jpeg,image/webp,application/pdf" required><small>${tr('PNG, JPG, WEBP או PDF עד 5MB.','PNG, JPG, WEBP or PDF up to 5MB.')}</small></div><div id="proof-error" class="error-text"></div><button class="btn primary">${tr('העלאת אישור תשלום','Upload payment proof')}</button></form>`);
  qs('#copy-phone',m).onclick=async()=>{try{await navigator.clipboard.writeText(d.bitPhone);toast(tr('המספר הועתק.','Number copied.'))}catch{toast(tr('לא ניתן להעתיק אוטומטית.','Could not copy automatically.'),'error')}};
  qs('#proof-form',m).onsubmit=async e=>{e.preventDefault();const file=new FormData(e.currentTarget).get('proof');if(!file||!file.size)return;if(file.size>5*1024*1024){qs('#proof-error',m).textContent=tr('הקובץ גדול מדי.','File too large.');return}const reader=new FileReader();reader.onload=async()=>{const btn=e.submitter;btn.disabled=true;btn.classList.add('loading');try{await api(`/api/orders/${order.id}/proof`,{method:'POST',body:JSON.stringify({name:file.name,dataUrl:reader.result})});toast(tr('האישור הועלה ונשלח לבדיקה.','Proof uploaded for review.'));m.remove();loadOrders()}catch(err){qs('#proof-error',m).textContent=err.message}finally{btn.disabled=false;btn.classList.remove('loading')}};reader.readAsDataURL(file)};
}
